let storageError=false,data=defaults(),game=null;
function normalizeProgress(raw){
 const d=defaults();if(raw?.version!==1)return d;
 d.completed=[...new Set((raw.completed??[]).filter(x=>Number.isInteger(x)&&x>=1&&x<=30))];
 for(let id=1;id<=30;id++){const step=raw.steps?.[id];if(Number.isInteger(step)&&step>=0&&step<4)d.steps[id]=step;const v=raw.stats?.[id];if(v)d.stats[id]={date:String(v.date??'').slice(0,10),errors:Number.isFinite(v.errors)?Math.max(0,v.errors):0,hints:Number.isFinite(v.hints)?Math.max(0,v.hints):0};}
 d.practice=Number.isInteger(raw.practice)?Math.max(0,raw.practice):0;
 d.days=Array.isArray(raw.days)?[...new Set(raw.days.filter(x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)))].slice(-365):[];
 for(const k of Object.keys(d.settings))if(typeof raw.settings?.[k]==='boolean')d.settings[k]=raw.settings[k];
 d.records=Array.isArray(raw.records)?raw.records.filter(r=>validateGame(r?.game)).slice(0,12).map(r=>({...r,date:String(r.date??'').slice(0,10),score:territory(r.game,r.game.dead??[],r.game.neutral??[])})):[];
 if(Number.isInteger(raw.resume?.id)&&raw.resume.id>=1&&raw.resume.id<=30)d.resume={id:raw.resume.id,step:d.steps[raw.resume.id]??0};
 return d;
}
