function say(text){if(!('speechSynthesis' in window)){toast('이 브라우저에서는 음성 안내를 지원하지 않아요. 글로 함께 배울 수 있어요.');return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';u.rate=.93;const voice=window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('ko'));if(voice)u.voice=voice;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('음성을 재생하지 못했어요. 화면의 설명으로 이어가세요.');};window.speechSynthesis.speak(u);}
let audioContext;
function stoneSound(){if(!data.settings.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),gain=audioContext.createGain();o.type='sine';o.frequency.setValueAtTime(550,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(160,audioContext.currentTime+.065);gain.gain.setValueAtTime(.07,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.09);o.connect(gain);gain.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.10);}catch{}}
