let svgSerial=0;
function boardHTML(board,size,{interactive=true,selected=[],hints=[],marks=[],last=null,ghost=null,deadStones=[],owned=null,neutralPoints=[],label='바둑판'}={}){
  const id=++svgSerial,gap=840/(size-1),r=gap*.41,px=p=>80+p%size*gap,py=p=>80+Math.floor(p/size)*gap;
  const drawStone=(p,c,opacity=1,placed=false)=>{const cx=c===1?893:360,cy=358;return `<g class="stone ${c===2?'white':''} ${placed?'placed':''}" opacity="${opacity}"><svg x="${px(p)-r}" y="${py(p)-r}" width="${r*2}" height="${r*2}" viewBox="${cx-50} ${cy-50} 100 100"><defs><clipPath id="stone-${id}-${p}-${opacity}"><circle cx="${cx}" cy="${cy}" r="49.5"/></clipPath></defs><image href="./assets/board-reference.png" width="1254" height="1254" clip-path="url(#stone-${id}-${p}-${opacity})"/></svg></g>`;};
  let out=`<div class="board-shell"><svg class="go-board" viewBox="0 0 1000 1000" role="group" aria-label="${esc(label)} ${size}줄"><image href="./assets/wood-board.png" width="1000" height="1000"/><g stroke="#493a25" stroke-width="2.5" opacity=".90">`;
  for(let i=0;i<size;i++){const a=80+i*gap;out+=`<path d="M80 ${a}H920M${a} 80V920"/>`;}out+='</g>';
  const stars=size===9?[20,24,40,56,60]:[12];for(const p of stars)out+=`<circle cx="${px(p)}" cy="${py(p)}" r="${size===9?7:8}" fill="#493a25"/>`;
  if(owned)owned.forEach((c,p)=>{if(c&&!board[p])out+=`<rect x="${px(p)-gap*.16}" y="${py(p)-gap*.16}" width="${gap*.32}" height="${gap*.32}" rx="3" fill="${c===1?'#242d27':'#fffef8'}" stroke="#6c6545" stroke-width="1.5"/>`;});
  for(const p of neutralPoints)if(!board[p])out+=`<path d="M${px(p)-gap*.10} ${py(p)-gap*.10}l${gap*.2} ${gap*.2}M${px(p)+gap*.10} ${py(p)-gap*.10}l${-gap*.2} ${gap*.2}" stroke="#467567" stroke-width="4"/>`;
  board.forEach((c,p)=>{if(c){out+=drawStone(p,c,deadStones.includes(p)?.32:1,p===last);if(p===last)out+=`<circle cx="${px(p)}" cy="${py(p)}" r="${r*.17}" fill="none" stroke="${c===1?'#f9f8f0':'#263c32'}" stroke-width="3"/>`;}});
  for(const p of marks)out+=`<circle cx="${px(p)}" cy="${py(p)}" r="${r*.68}" fill="none" stroke="${board[p]===1?'#e9d798':'#3d775e'}" stroke-width="4" stroke-dasharray="8 6"/>`;
  for(const p of hints)if(!selected.includes(p))out+=`<g class="hint-dot"><circle cx="${px(p)}" cy="${py(p)}" r="${gap*.20}" fill="#dfeac0" fill-opacity=".75" stroke="#48713e" stroke-width="4"/><circle cx="${px(p)}" cy="${py(p)}" r="${gap*.06}" fill="#48713e"/></g>`;
  for(const p of selected)out+=`<g><circle cx="${px(p)}" cy="${py(p)}" r="${gap*.24}" fill="#436d45" stroke="#f4f2d7" stroke-width="3"/><path d="m${px(p)-gap*.1} ${py(p)} ${gap*.07} ${gap*.075} ${gap*.14} ${-gap*.17}" fill="none" stroke="white" stroke-width="4"/></g>`;
  if(ghost&&!board[ghost.p])out+=drawStone(ghost.p,ghost.color,.48);
  if(interactive)for(let p=0;p<board.length;p++)out+=`<g class="intersection" data-pos="${p}" role="button" tabindex="${p===0?0:-1}" aria-label="${Math.floor(p/size)+1}행 ${p%size+1}열 ${board[p]===1?'흑돌':board[p]===2?'백돌':'빈자리'}"><circle class="touch-glow" cx="${px(p)}" cy="${py(p)}" r="${gap*.14}"/><circle class="focus-ring" cx="${px(p)}" cy="${py(p)}" r="${gap*.29}"/><rect x="${px(p)-gap*.48}" y="${py(p)-gap*.48}" width="${gap*.96}" height="${gap*.96}" fill="transparent"/></g>`;
  return out+'</svg></div>';
}
